import React,{useState} from 'react';import {supabase} from '../lib/supabase';import toast from 'react-hot-toast';import {Link} from 'react-router-dom';
export default function ForgotPassword(){const [email,setEmail]=useState('');const [loading,setLoading]=useState(false);const [sent,setSent]=useState(false);const handleSubmit=async e=>{e.preventDefault();setLoading(true);const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin+'/reset-password'});if(error)toast.error(error.message);else{setSent(true);toast.success('Reset link sent');}setLoading(false);};if(sent)return(<div className="min-h-screen flex items-center justify-center"><div className="bg-white p-8 rounded-xl shadow-md w-96 text-center"><h1>Check Email</h1><p>Sent to {email}</p><Link to="/login" className="text-green-600">Return to Login</Link></div></div>);return(<div className="min-h-screen flex items-center justify-center"><form onSubmit={handleSubmit} className="bg-white p-8 rounded-xl shadow-md w-96"><h1>Forgot Password</h1><input type="email" placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)} className="w-full p-3 border rounded mb-4" required/><button disabled={loading} className="w-full bg-green-600 text-white p-3 rounded">{loading?'Sending...':'Send Reset Link'}</button><div className="mt-4"><Link to="/login">Back to Login</Link></div></form></div>);}
